            C#

    using System;
using System.Collections.Generic;

class GfG {
    // Constructs an adjacency list for a directed graph
    static List<int>[] constructAdj(int V, int[, ] edges)
    {
        var adj = new List<int>[ V ];
        for (int i = 0; i < V; i++)
            adj[i] = new List<int>();

        int edgeCount = edges.GetLength(0);
        for (int i = 0; i < edgeCount; i++) {
            int from = edges[i, 0];
            int to = edges[i, 1];
            adj[from].Add(to);
        }

        return adj;
    }

    // Utility function for DFS traversal and cycle
    // detection
    static bool dfsutil(int u, List<int>[] adj, int[] color)
    {
        const int gray = 1, black = 2;

        color[u] = gray;

        foreach(int v in adj[u])
        {
            if (color[v] == gray)
                return true;

            if (color[v] == 0 && dfsutil(v, adj, color))
                return true;
        }

        color[u] = black;
        return false;
    }

    // Main function to detect cycle in a directed graph
    static bool isCyclic(int V, int[, ] edges)
    {
        int[] color
            = new int[V]; // 0 - white (unvisited), 1 - gray
                          // (visiting), 2 - black (visited)
        var adj = constructAdj(V, edges);

        for (int i = 0; i < V; i++) {
            if (color[i] == 0) {
                if (dfsutil(i, adj, color))
                    return true;
            }
        }

        return false;
    }

    static void Main()
    {
        int V = 4;
        int[, ] edges
            = new int[, ] { { 0, 1 }, { 0, 2 }, { 1, 2 },
                            { 2, 0 }, { 2, 3 }, { 3, 3 } };

        Console.WriteLine(isCyclic(V, edges) ? "true"
                                             : "false");
    }
}


            JavaScript

    // Constructs an adjacency list for a directed graph
function constructAdj(V, edges)
{
    const adj = Array.from({length : V}, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
    }
    return adj;
}

// Utility function for DFS traversal and cycle detection
function dfsutil(u, adj, color)
{
    const gray = 1, black = 2;
    color[u] = gray; // mark as visiting

    for (const v of adj[u]) {
        if (color[v] === gray)
            return true; // found a back edge (cycle)
        if (color[v] === 0 && dfsutil(v, adj, color))
            return true; // visit unvisited node
    }

    color[u] = black; // mark as visited
    return false;
}

// Main function to detect cycle in a directed graph
function isCyclic(V, edges)
{
    const color = Array(V).fill(0); // 0 - white (unvisited)
    const adj = constructAdj(V, edges);

    for (let i = 0; i < V; i++) {
        if (color[i] === 0 && dfsutil(i, adj, color)) {
            return true;
        }
    }
    return false;
}

// Driver code
const V = 4;
const edges = [
    [ 0, 1 ], [ 0, 2 ], [ 1, 2 ], [ 2, 0 ], [ 2, 3 ],
    [ 3, 3 ]
];

console.log(isCyclic(V, edges) ? "true" : "false");

Outputtrue
Time complexity: O(V + E), where V is the number of vertices and E is the number of edges in the graph.Space Complexity: O(V), Since an extra color array is needed of size V.We do not count the adjacency list in auxiliary space as it is necessary for representing the input graph.
